import { Component, inject, OnInit } from '@angular/core';
import { ChartData, ChartOptions, Chart, registerables } from 'chart.js';
import ChartDataLabels from 'chartjs-plugin-datalabels';
import { DashboardFacadeService } from './dashboard-facade.service';

Chart.register(...registerables, ChartDataLabels);

@Component({
  selector: "app-dashboard",
  templateUrl: "./dashboard.component.html",
  styleUrls: ["./dashboard.component.scss"],
  standalone: false
})
export class DashboardComponent implements OnInit {

  public facade = inject(DashboardFacadeService);

  // ===== Sesión / rol =====
  public sesion: any = null;
  public idTipoUsuario = 0;
  public esAdmin = false;
  public esVendedor = false;
  public esOperativo = false;   // Bodega / Temporal / Tienda

  // paleta Augajo
  private readonly rojo = '#E01A1A';
  private readonly negro = '#1A1A1A';
  private readonly verde = '#2E7D5B';
  private readonly ambar = '#E0A82E';
  private readonly gris = '#9A9A9A';
  private readonly paleta = ['#E01A1A', '#1A1A1A', '#2E7D5B', '#E0A82E', '#2563EB', '#7C3AED', '#8A8A8A'];

  // moneda para tooltips/ejes
  private L = (v: any) => 'L. ' + Number(v).toLocaleString('en-US', { minimumFractionDigits: 2 });
  private L0 = (v: any) => 'L. ' + Number(v).toLocaleString('en-US', { maximumFractionDigits: 0 });

  // ============================================================
  // CONFIGS DE CHARTS
  // ============================================================

  // --- Pedidos por mes (línea) ---
  public pedMesData: ChartData<'line'> = { labels: [], datasets: [] };
  public pedMesOptions: ChartOptions<'line'> = {
    responsive: true, maintainAspectRatio: false,
    plugins: { legend: { display: false }, datalabels: { display: false } as any },
    scales: { y: { beginAtZero: true, ticks: { precision: 0 } }, x: { grid: { display: false } } }
  };

  // --- Pedidos por estado (dona) ---
  public pedEstadoData: ChartData<'doughnut'> = { labels: [], datasets: [] };
  public pedEstadoOptions: ChartOptions<'doughnut'> = {
    responsive: true, maintainAspectRatio: false, cutout: '62%',
    plugins: {
      legend: { position: 'right', labels: { boxWidth: 12, padding: 12 } },
      datalabels: { color: '#fff', font: { weight: 'bold' } } as any
    }
  };

  // --- Top productos (barra) ---
  public topData: ChartData<'bar'> = { labels: [], datasets: [] };
  public topOptions: ChartOptions<'bar'> = {
    indexAxis: 'y', responsive: true, maintainAspectRatio: false,
    plugins: { legend: { display: false }, datalabels: { anchor: 'end', align: 'end', color: '#1A1A1A' } as any },
    scales: { x: { beginAtZero: true, ticks: { precision: 0 } }, y: { grid: { display: false } } }
  };

  // --- Inventario por categoría (dona) ---
  public categoriaData: ChartData<'doughnut'> = { labels: [], datasets: [] };
  public categoriaOptions: ChartOptions<'doughnut'> = {
    responsive: true, maintainAspectRatio: false, cutout: '62%',
    plugins: {
      legend: { position: 'right', labels: { boxWidth: 12, padding: 12 } },
      datalabels: { display: false } as any
    }
  };

  // --- Ingresos por mes (línea) ---
  public ingMesData: ChartData<'line'> = { labels: [], datasets: [] };
  public ingMesOptions: ChartOptions<'line'> = {
    responsive: true, maintainAspectRatio: false,
    plugins: {
      legend: { display: false }, datalabels: { display: false } as any,
      tooltip: { callbacks: { label: (c: any) => this.L(c.raw) } }
    },
    scales: { y: { beginAtZero: true, ticks: { callback: (v: any) => this.L0(v) } }, x: { grid: { display: false } } }
  };

  // --- Ingresos por día (línea) ---
  public ingDiaData: ChartData<'line'> = { labels: [], datasets: [] };
  public ingDiaOptions: ChartOptions<'line'> = {
    responsive: true, maintainAspectRatio: false,
    plugins: {
      legend: { display: false }, datalabels: { display: false } as any,
      tooltip: { callbacks: { label: (c: any) => this.L(c.raw) } }
    },
    scales: { y: { beginAtZero: true, ticks: { callback: (v: any) => this.L0(v) } }, x: { grid: { display: false } } }
  };

  // --- Bodega vs Consigna (dona) ---
  public origenData: ChartData<'doughnut'> = { labels: [], datasets: [] };
  public origenOptions: ChartOptions<'doughnut'> = {
    responsive: true, maintainAspectRatio: false, cutout: '62%',
    plugins: {
      legend: { position: 'right', labels: { boxWidth: 12, padding: 12 } },
      datalabels: { display: false } as any,
      tooltip: { callbacks: { label: (c: any) => c.label + ': ' + this.L(c.raw) } }
    }
  };

  // --- Top revendedoras (barra) ---
  public revendedorasData: ChartData<'bar'> = { labels: [], datasets: [] };
  public revendedorasOptions: ChartOptions<'bar'> = {
    indexAxis: 'y', responsive: true, maintainAspectRatio: false,
    plugins: {
      legend: { display: false },
      datalabels: { anchor: 'end', align: 'end', color: '#1A1A1A', formatter: (v: any) => this.L0(v) } as any
    },
    scales: { x: { beginAtZero: true, ticks: { callback: (v: any) => this.L0(v) } }, y: { grid: { display: false } } }
  };

  // --- Top productos por ingreso (barra) ---
  public topIngresoData: ChartData<'bar'> = { labels: [], datasets: [] };
  public topIngresoOptions: ChartOptions<'bar'> = {
    indexAxis: 'y', responsive: true, maintainAspectRatio: false,
    plugins: {
      legend: { display: false },
      datalabels: { anchor: 'end', align: 'end', color: '#1A1A1A', formatter: (v: any) => this.L0(v) } as any
    },
    scales: { x: { beginAtZero: true, ticks: { callback: (v: any) => this.L0(v) } }, y: { grid: { display: false } } }
  };

  constructor() {
    this.cargarSesion();
  }

  ngOnInit(): void {
    this.suscribir();
    this.cargarTodo();
  }

  // ============================================================
  // Sesión / rol
  // ============================================================
  private cargarSesion() {
    try {
      // ajusta la clave al nombre real de tu sesión en localStorage
      this.sesion = JSON.parse(localStorage.getItem('usuario_data') || localStorage.getItem('usuario') || 'null');
    } catch { this.sesion = null; }

    this.idTipoUsuario = Number(this.sesion?.IdTipoUsuario ?? 0);
    this.esAdmin     = this.idTipoUsuario === 1;
    this.esVendedor  = this.idTipoUsuario === 2;
    this.esOperativo = !this.esAdmin && !this.esVendedor;   // bodega / temporal / tienda
  }


  cargarTodo() {
    this.facade.CargarDashboard(this.idTipoUsuario, this.sesion?.IdUsuario ?? 0, 30, 5);
  }

  private suscribir() {
    this.facade.responsePedMes$.subscribe(rows => this.armarPedMes(rows));
    this.facade.responsePedEstado$.subscribe(rows => this.armarPedEstado(rows));
    this.facade.responseTopProductos$.subscribe(rows => this.armarTop(rows));
    this.facade.responseInvCategoria$.subscribe(rows => this.armarCategoria(rows));
    this.facade.responseIngMes$.subscribe(rows => this.armarIngMes(rows));
    this.facade.responseIngDia$.subscribe(rows => this.armarIngDia(rows));
    this.facade.responseIngOrigen$.subscribe(rows => this.armarOrigen(rows));
    this.facade.responseTopRevendedoras$.subscribe(rows => this.armarRevendedoras(rows));
  }

  private armarPedMes(rows: any[]) {
    this.pedMesData = {
      labels: (rows || []).map(r => r.periodo),
      datasets: [{
        data: (rows || []).map(r => r.cantidad),
        label: 'Pedidos', borderColor: this.rojo, backgroundColor: 'rgba(224,26,26,0.08)',
        fill: true, tension: 0.35, pointBackgroundColor: this.rojo, pointRadius: 3
      }]
    };
  }

  private armarPedEstado(rows: any[]) {
    this.pedEstadoData = {
      labels: (rows || []).map(r => r.estado),
      datasets: [{
        data: (rows || []).map(r => r.cantidad),
        backgroundColor: (rows || []).map((_, i) => this.paleta[i % this.paleta.length]),
        borderWidth: 0
      }]
    };
  }

  private armarTop(rows: any[]) {
    this.topData = {
      labels: (rows || []).map(r => r.producto),
      datasets: [{
        data: (rows || []).map(r => r.unidades_vendidas ?? r.unidades),
        label: 'Unidades', backgroundColor: this.negro, borderRadius: 6, maxBarThickness: 26
      }]
    };
  }

  private armarCategoria(rows: any[]) {
    this.categoriaData = {
      labels: (rows || []).map(r => r.categoria ?? 'Sin categoría'),
      datasets: [{
        data: (rows || []).map(r => r.valor),
        backgroundColor: (rows || []).map((_, i) => this.paleta[i % this.paleta.length]),
        borderWidth: 0
      }]
    };
  }

  private armarIngMes(rows: any[]) {
    this.ingMesData = {
      labels: (rows || []).map(r => r.periodo),
      datasets: [{
        data: (rows || []).map(r => r.ingresos),
        label: 'Ingresos', borderColor: this.rojo, backgroundColor: 'rgba(224,26,26,0.08)',
        fill: true, tension: 0.35, pointBackgroundColor: this.rojo, pointRadius: 3
      }]
    };
  }

  private armarIngDia(rows: any[]) {
    this.ingDiaData = {
      labels: (rows || []).map(r => {
        const f = new Date(r.fecha);
        return `${f.getDate()}/${f.getMonth() + 1}`;
      }),
      datasets: [{
        data: (rows || []).map(r => r.ingresos),
        label: 'Ingresos', borderColor: this.negro, backgroundColor: 'rgba(26,26,26,0.06)',
        fill: true, tension: 0.35, pointBackgroundColor: this.negro, pointRadius: 2
      }]
    };
  }

  private armarOrigen(rows: any[]) {
    this.origenData = {
      labels: (rows || []).map(r => r.origen),
      datasets: [{
        data: (rows || []).map(r => r.ingresos),
        backgroundColor: (rows || []).map(r => r.origen === 'Consigna' ? this.rojo : this.negro),
        borderWidth: 0
      }]
    };
  }

  private armarRevendedoras(rows: any[]) {
    this.revendedorasData = {
      labels: (rows || []).map(r => r.revendedora),
      datasets: [{
        data: (rows || []).map(r => r.ingresos),
        label: 'Ingresos', backgroundColor: this.rojo, borderRadius: 6, maxBarThickness: 26
      }]
    };
  }

  variacionPedidos(kpi: any): number {
    if (!kpi || !kpi.pedidos_mes_anterior) { return 0; }
    return Math.round(((kpi.pedidos_mes - kpi.pedidos_mes_anterior) / kpi.pedidos_mes_anterior) * 100);
  }

  variacionIngresos(kpi: any): number {
    if (!kpi || !kpi.ingresos_mes_anterior) { return 0; }
    return Math.round(((kpi.ingresos_mes - kpi.ingresos_mes_anterior) / kpi.ingresos_mes_anterior) * 100);
  }

  ticketPromedio(kpi: any): number {
    if (!kpi || !kpi.pedidos_mes) { return 0; }
    return kpi.ingresos_mes / kpi.pedidos_mes;
  }
}