import { HttpErrorResponse } from "@angular/common/http";
import { inject, Injectable } from "@angular/core";
import { EMPTY, Observable } from "rxjs";
import { BehaviorSubject } from "rxjs";
import { catchError, tap } from "rxjs/operators";
import { ToastrServiceLocal } from "../../../services/toast/toastr.service";
import { DataApiService } from "../../../services/data-api.service";
import { MensajesHttpService } from "../../../utils/mensajesHttp/mensajes-http.service";


@Injectable({
  providedIn: "root",
})
export class DashboardFacadeService {

  private dataApi = inject(DataApiService);
  private _mensajesHttp = inject(MensajesHttpService);

  // ---- Inventario ----
  private InvKpis$ = new BehaviorSubject<any>(null);
  public responseInvKpis$: Observable<any> = this.InvKpis$.asObservable();

  private TopProductos$ = new BehaviorSubject<any[]>([]);
  public responseTopProductos$: Observable<any[]> = this.TopProductos$.asObservable();

  private InvCategoria$ = new BehaviorSubject<any[]>([]);
  public responseInvCategoria$: Observable<any[]> = this.InvCategoria$.asObservable();

  private BajoMinimo$ = new BehaviorSubject<any[]>([]);
  public responseBajoMinimo$: Observable<any[]> = this.BajoMinimo$.asObservable();

  private PorVencer$ = new BehaviorSubject<any[]>([]);
  public responsePorVencer$: Observable<any[]> = this.PorVencer$.asObservable();

  private PedKpis$ = new BehaviorSubject<any>(null);
  public responsePedKpis$: Observable<any> = this.PedKpis$.asObservable();

  private PedEstado$ = new BehaviorSubject<any[]>([]);
  public responsePedEstado$: Observable<any[]> = this.PedEstado$.asObservable();

  private PedMes$ = new BehaviorSubject<any[]>([]);
  public responsePedMes$: Observable<any[]> = this.PedMes$.asObservable();

  private PedDia$ = new BehaviorSubject<any[]>([]);
  public responsePedDia$: Observable<any[]> = this.PedDia$.asObservable();

  private PedMetodoPago$ = new BehaviorSubject<any[]>([]);
  public responsePedMetodoPago$: Observable<any[]> = this.PedMetodoPago$.asObservable();

  private IngKpis$ = new BehaviorSubject<any[]>([]);
  public responseIngKpis$: Observable<any[]> = this.IngKpis$.asObservable();

  private IngMes$ = new BehaviorSubject<any[]>([]);
  public responseIngMes$: Observable<any[]> = this.IngMes$.asObservable();

  private IngDia$ = new BehaviorSubject<any[]>([]);
  public responseIngDia$: Observable<any[]> = this.IngDia$.asObservable();

  private IngOrigen$ = new BehaviorSubject<any[]>([]);
  public responseIngOrigen$: Observable<any[]> = this.IngOrigen$.asObservable();

  private TopRevendedoras$ = new BehaviorSubject<any[]>([]);
  public responseTopRevendedoras$: Observable<any[]> = this.TopRevendedoras$.asObservable();


  private t(data: any, i: number) {
    return data?.[`Table${i}`] ?? [];
  }
  private fila(data: any, i: number) {
    return data?.[`Table${i}`]?.[0] ?? null;
  }

  // rol: idTipoUsuario (1=Admin, 2=Vendedor, otro=operativo)
  CargarDashboard(idTipoUsuario: number, idUsuario: number, dias: number = 30, limite: number = 5) {
    const params = { idTipoUsuario, idUsuario, dias, limite };

    return this.dataApi.PostDataApi(`dashboard/v1/inventario-productos`, params).pipe(
      tap((result: any) => {
        const d = result?.data ?? {};

        if (idTipoUsuario === 1) {
          // ADMIN
          this.InvKpis$.next(this.fila(d, 0));
          this.PedKpis$.next(this.fila(d, 1));
          this.IngKpis$.next(this.fila(d, 2));
          this.PedMes$.next(this.t(d, 3));
          this.PedEstado$.next(this.t(d, 4));
          this.IngMes$.next(this.t(d, 5));
          this.IngDia$.next(this.t(d, 6));
          this.IngOrigen$.next(this.t(d, 7));
          this.TopProductos$.next(this.t(d, 8));
          this.TopRevendedoras$.next(this.t(d, 9));
          this.InvCategoria$.next(this.t(d, 10));
          this.BajoMinimo$.next(this.t(d, 11));
          this.PorVencer$.next(this.t(d, 12));

        } else if (idTipoUsuario === 2) {
          // VENDEDOR
          this.IngKpis$.next(this.fila(d, 0));   // reutilizo el subject de KPIs
          this.IngDia$.next(this.t(d, 1));
          this.IngOrigen$.next(this.t(d, 2));
          this.TopProductos$.next(this.t(d, 3));

        } else {
          // OPERATIVO (Bodega / Temporal / Tienda)
          this.PedKpis$.next(this.fila(d, 0));   // conteos operativos
          this.PedEstado$.next(this.t(d, 1));
        }
      }),
      catchError((error: HttpErrorResponse) => {
        this._mensajesHttp.mostrarErrorHttp(error, 'Error al cargar el dashboard', '');
        return EMPTY;
      })
    ).subscribe();
  }
}
